from typing import List


def read_fasta(path: str):
    """Read a FASTA file, returning a list of (header, sequence) tuples."""
    records = []
    header = None
    seq_lines: List[str] = []
    with open(path) as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            if line.startswith(">"):
                if header is not None:
                    records.append((header, "".join(seq_lines)))
                header = line[1:]
                seq_lines = []
            else:
                seq_lines.append(line)
    if header is not None:
        records.append((header, "".join(seq_lines)))
    return records


def consensus(sequences: List[str]) -> str:
    """Return the majority-rule consensus of equal-length sequences.

    Per column: most frequent base wins; ties for the top count yield 'N'.
    Raises ValueError if sequences have unequal length or input is empty.
    """
    if not sequences:
        raise ValueError("no sequences provided")
    length = len(sequences[0])
    if any(len(s) != length for s in sequences):
        raise ValueError("sequences must be equal length")

    out = []
    for i in range(length):
        counts = {}
        for s in sequences:
            base = s[i]
            counts[base] = counts.get(base, 0) + 1
        top = max(counts.values())
        winners = [b for b, c in counts.items() if c == top]
        out.append(winners[0] if len(winners) == 1 else "N")
    return "".join(out)


def count_profile(sequences: List[str]) -> List[str]:
    """Per-column TSV rows of 'base:count' pairs (deterministic order)."""
    length = len(sequences[0])
    rows = []
    for i in range(length):
        counts = {}
        for s in sequences:
            counts[s[i]] = counts.get(s[i], 0) + 1
        row = "\t".join(f"{b}:{c}" for b, c in sorted(counts.items()))
        rows.append(row)
    return rows


if __name__ == "__main__":
    import sys

    path = sys.argv[1]
    seqs = [seq for _, seq in read_fasta(path)]
    print(consensus(seqs))
